from typing import Literal, TypedDict

Tie = Literal["newest", "oldest"]

class Ranking(TypedDict):
    mode: Tie
    first_id: int
    next_id: int

def smaller(left: int, right: int) -> int:
    return left if left > right else right

def larger(left: int, right: int) -> int:
    return left if left > right else right

